"""Embed preview-size Kense artwork in copy-source installs. Requires Pillow."""
from io import BytesIO
from pathlib import Path

from PIL import Image

root = Path(__file__).resolve().parents[1]
output = [
    "//! Kense artwork for compact controls, sampled from the website's transparent marks.",
    "// Generated by scripts/sync-brand-marks.py. Keep these bytes in the copy-source package.",
]

for mode in ("light", "dark"):
    with Image.open(root / f"website/public/assets/mark-{mode}.png") as image:
        image = image.resize((72, 72), Image.Resampling.LANCZOS)
    encoded = BytesIO()
    image.save(encoded, format="PNG", optimize=True)
    # A plain Rust literal also works with older, text-only registry clients.
    data = encoded.getvalue()
    output += ["", f'pub(crate) const {mode.upper()}: &[u8] = b"\\']
    for start in range(0, len(data), 24):
        escaped = "".join(f"\\x{b:02x}" for b in data[start:start + 24])
        output.append(f"    {escaped}\\")
    output.append('";')

(root / "registry/src/primitives/kense_mark.rs").write_text("\n".join(output) + "\n")
